// Regenerates src/generated/slide-manifest.ts from the slides/ directory.
//
// A store app cannot evaluate code at runtime (CSP: script-src 'self'
// 'wasm-unsafe-eval'; the sole 'unsafe-eval' exception is host-authored, for
// the bundled Themes editor, in unpackaged dev builds — spec §4.5). Upstream's
// per-slide Vite compile therefore has no runtime equivalent here, so slides
// are ordinary app source and the HOST's esbuild compiles them at build time.
// This manifest is the static import map that makes that possible.
//
// Run after adding or removing a slide:  node vendor/build-slide-manifest.mjs
import { readdir, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const slidesDir = path.join(appRoot, 'slides')

const entries = await readdir(slidesDir).catch(() => [])
const ids = []
for (const entry of entries.sort()) {
  if (entry.startsWith('.')) continue
  const info = await stat(path.join(slidesDir, entry)).catch(() => null)
  if (!info?.isDirectory()) continue
  const hasSource = await stat(path.join(slidesDir, entry, 'index.tsx'))
    .then(() => true)
    .catch(() => false)
  if (hasSource) ids.push(entry)
}

const imports = ids
  .map((id, i) => `import * as slide${i} from '../../slides/${id}/index'`)
  .join('\n')
const rows = ids.map((id, i) => `  ${JSON.stringify(id)}: slide${i} as unknown as SlideModule,`).join('\n')

const code = `// GENERATED by vendor/build-slide-manifest.mjs — do not edit.
//
// Static imports so the host's esbuild compiles every slide into the bundle.
// See that script for why runtime compilation is impossible here.
import type { SlideModule } from '@/lib/sdk'
${imports}

export const SLIDE_MODULES: Record<string, SlideModule> = {
${rows}
}

export const SLIDE_IDS: string[] = ${JSON.stringify(ids, null, 2).replace(/\n/g, '\n')}
`

await writeFile(path.join(appRoot, 'src/generated/slide-manifest.ts'), code)
console.log(`slide manifest: ${ids.length} slides —`, ids.join(', '))
